export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const v = u - g * t;
  const y = Math.max(0, u * t - g * t * t / 2);
  const F = m * g;
  const H = u * u / (2 * g);
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 240, h: 376, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 260, y: 34, w: 370, h: 376, title: 'Velocity over time', state: '' }));
  o.push(sdk.axis('axis.h', { x: 70, y: 370, length: 290, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const py = 370 - y / 2.2 * 290;
  o.push(sdk.circle('ball.toss', 120, py, 24));
  o.push(...sdk.vector('vec.v', { x: 120, y: py }, { value: v, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 150, y: py }, { value: -g, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
  o.push(sdk.callout(165, Math.min(py, 330) - 10, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const full = [], cur = [];
  const tm = 1.8;
  for (let i = 0; i <= 12; i++) { const x = tm * i / 12; full.push({ x, y: sdk.clamp(u - g * x, -5.5, 5.5) }); }
  const n = 12;
  for (let i = 0; i <= n; i++) { const x = t * i / n; cur.push({ x, y: sdk.clamp(u - g * x, -5.5, 5.5) }); }
  const series = [{ label: 'v = u - g t (full)', kind: 'line', points: full }, { label: 'v up to now', kind: 'line', points: cur }];
  o.push(sdk.plot('plot.vt', { x: 275, y: 70, w: 345, h: 330, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  o.push(sdk.text('plot.vt.note', 450, 60, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s²', { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F } };
}
